const DESKTOP_QUERY=matchMedia("(min-width: 768px)"),AWAY_CLASS="sticky-cta--away",ARMED_CLASS="sticky-cta-armed";function ready(e){document.readyState==="loading"?document.addEventListener("DOMContentLoaded",e):e()}ready(function(){const e=document.querySelector("[data-sticky-cta]");if(!e||DESKTOP_QUERY.matches)return;e.hidden=!1,document.documentElement.classList.add(ARMED_CLASS);const a=document.querySelectorAll(".contact-band, #enquiry");if(a.length){const t=new Set,d=new IntersectionObserver(n=>{n.forEach(c=>{c.isIntersecting?t.add(c.target):t.delete(c.target)});const s=t.size>0;e.classList.toggle(AWAY_CLASS,s),e.inert=s});a.forEach(n=>d.observe(n))}DESKTOP_QUERY.addEventListener("change",t=>{t.matches&&(e.hidden=!0,document.documentElement.classList.remove(ARMED_CLASS))})});
